def _operator(panel, z):
    from scipy.optimize import least_squares
    (u, v) = (np.asarray(panel[k], dtype=float) for k in ('u', 'v'))

    def warp(x, p):
        return np.sign(x) * np.maximum(np.abs(x) - p[0], 0.0) ** p[1]

    def profile(p):
        h = _affine(warp(u, p))
        return (h @ _fit(h, v) - v).ravel()
    p = least_squares(profile, [0.35, 1.5], bounds=([0, 0.2], [0.7, 4]), gtol=1e-13).x
    q = warp(z, p)
    return (q, _affine(q) @ _fit(_affine(warp(u, p)), v))
